package com.company.logicdelete.runtime;
public class RuntimeTraceProperties {private boolean enabled=false,collectHttpEntry=true;private String appName="unknown-app",env="unknown",outputPath="./logs/sql-runtime-trace.log",sqlOutputMode="HASH_ONLY",traceHeader="X-Trace-Id";private int maxSqlSampleLength=2000;private double sampleRate=1.0;public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public boolean isCollectHttpEntry(){return collectHttpEntry;}public void setCollectHttpEntry(boolean v){collectHttpEntry=v;}public String getAppName(){return appName;}public void setAppName(String v){appName=v;}public String getEnv(){return env;}public void setEnv(String v){env=v;}public String getOutputPath(){return outputPath;}public void setOutputPath(String v){outputPath=v;}public String getSqlOutputMode(){return sqlOutputMode;}public void setSqlOutputMode(String v){sqlOutputMode=v;}public String getTraceHeader(){return traceHeader;}public void setTraceHeader(String v){traceHeader=v;}public int getMaxSqlSampleLength(){return maxSqlSampleLength;}public void setMaxSqlSampleLength(int v){maxSqlSampleLength=v;}public double getSampleRate(){return sampleRate;}public void setSampleRate(double v){sampleRate=Math.max(0,Math.min(1,v));}}
